export const getListDatasetsUrl = (params?: ListDatasetsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/datasets?${stringifiedParams}`
    : `/api/datasets`;
};

export const listDatasets = async (
  params?: ListDatasetsParams,
  options?: RequestInit,
): Promise<Dataset[]> => {
  return customFetch<Dataset[]>(getListDatasetsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListDatasetsQueryKey = (params?: ListDatasetsParams) => {
  return [`/api/datasets`, ...(params ? [params] : [])] as const;
};

export const getListDatasetsQueryOptions = <
  TData = Awaited<ReturnType<typeof listDatasets>>,
  TError = ErrorType<unknown>,
>(
  params?: ListDatasetsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listDatasets>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getListDatasetsQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listDatasets>>> = ({
    signal,
  }) => listDatasets(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listDatasets>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListDatasetsQueryResult = NonNullable<
  Awaited<ReturnType<typeof listDatasets>>
>;
export type ListDatasetsQueryError = ErrorType<unknown>;

/**
 * @summary List available open datasets
 */

export function useListDatasets<
  TData = Awaited<ReturnType<typeof listDatasets>>,
  TError = ErrorType<unknown>,
>(
  params?: ListDatasetsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listDatasets>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getListDatasetsQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
